import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        Solver solver = new Solver();
        solver.solve(in, out);
        out.close();
    }

    static class Solver {
        long MOD = 998244353L;
        long[] fact;
        long[] invFact;

        void solve(InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            init(n + m);

            long phaseSize = 1;
            long p = 1;
            for (int i = 0; p != 0; i++) {
                p = mult(p, n - i, smallInv(n + m - i));
                phaseSize = add(phaseSize, p);
            }

            long answer = 0;
            for (int k = 1; k <= n; k++) {
                long numPhases = mult(m + k, smallInv(k));
                long term = mult(ncr(n, k), numPhases, phaseSize);
                if ((k & 1) == 1) answer = add(answer, term);
                else answer = subtract(answer, term);
            }

            out.println(answer);
        }

        void init(int max) {
            fact = new long[max + 1];
            invFact = new long[max + 1];
            fact[0] = 1;
            for (int i = 1; i <= max; i++) fact[i] = fact[i - 1] * i % MOD;
            invFact[max] = inv(fact[max]);
            for (int i = max; i >= 1; i--) invFact[i - 1] = invFact[i] * i % MOD;
        }

        long ncr(int n, int r) {
            if (r < 0 || n < r) return 0;
            return mult(fact[n], invFact[r], invFact[n - r]);
        }

        long smallInv(int x) {
            return mult(invFact[x], fact[x - 1]);
        }

        long mult(long... xs) {
            long r = 1;
            for (long x : xs) r = r * x % MOD;
            return r;
        }

        long add(long a, long b) {
            long v = a + b;
            return v < MOD ? v : v - MOD;
        }

        long subtract(long a, long b) {
            long v = a - b;
            return v < 0 ? v + MOD : v;
        }

        long inv(long a) {
            long g = MOD, x = 0, y = 1;
            for (long r = a; r != 0; ) {
                long q = g / r;
                g %= r;
                long tmp = g;
                g = r;
                r = tmp;
                x -= q * y;
                tmp = x;
                x = y;
                y = tmp;
            }
            if (g != 1) throw new AssertionError();
            x %= MOD;
            if (x < 0) x += MOD;
            return x;
        }
    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }
    }
}
